from AlgorithmImports import *


class ExactStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma200 = SimpleMovingAverage(200)
        self.spy_sma50 = SimpleMovingAverage(50)
        self.aapl_rsi14 = RelativeStrengthIndex(14)

        self.spy_lot = 0
        self.aapl_lot = 0

        self.previous_spy_close = None
        self.previous_spy_sma200 = None
        self.previous_spy_sma50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data: Slice):
        spy_bar = data.Bars.get(self.spy)
        aapl_bar = data.Bars.get(self.aapl)

        if spy_bar is not None:
            self.spy_sma200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma50.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            self.aapl_rsi14.Update(aapl_bar.EndTime, aapl_bar.Close)

            if self.previous_aapl_close is not None:
                if aapl_bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close

        if self.IsWarmingUp:
            if spy_bar is not None:
                if self.spy_sma200.IsReady:
                    self.previous_spy_sma200 = self.spy_sma200.Current.Value
                if self.spy_sma50.IsReady:
                    self.previous_spy_sma50 = self.spy_sma50.Current.Value
                self.previous_spy_close = spy_bar.Close
            return

        all_bars_present = all(
            data.Bars.get(symbol) is not None
            for symbol in self.symbols.values()
        )

        if not all_bars_present:
            if spy_bar is not None:
                if self.spy_sma200.IsReady:
                    self.previous_spy_sma200 = self.spy_sma200.Current.Value
                if self.spy_sma50.IsReady:
                    self.previous_spy_sma50 = self.spy_sma50.Current.Value
                self.previous_spy_close = spy_bar.Close
            return

        spy_close_crossed_below_50 = (
            spy_bar is not None
            and self.spy_sma50.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma50 is not None
            and self.previous_spy_close <= self.previous_spy_sma50
            and spy_bar.Close > self.spy_sma50.Current.Value
        )

        spy_close_crossed_above_200 = (
            spy_bar is not None
            and self.spy_sma200.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma200 is not None
            and self.previous_spy_close <= self.previous_spy_sma200
            and spy_bar.Close > self.spy_sma200.Current.Value
        )

        spy_close_crossed_below_50 = (
            spy_bar is not None
            and self.spy_sma50.IsReady
            and self.previous_spy_close is not None
            and self.previous_spy_sma50 is not None
            and self.previous_spy_close >= self.previous_spy_sma50
            and spy_bar.Close < self.spy_sma50.Current.Value
        )

        aapl_sell_reason = (
            self.aapl_rsi14.IsReady
            and self.aapl_rsi14.Current.Value > 60
        )

        if self.spy_lot > 0 and spy_close_crossed_below_50:
            self.MarketOrder(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and aapl_sell_reason:
            self.MarketOrder(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_close_crossed_above_200:
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value // spy_bar.Close)

            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 // aapl_bar.Close)

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.aapl_lot = quantity

        if spy_bar is not None:
            if self.spy_sma200.IsReady:
                self.previous_spy_sma200 = self.spy_sma200.Current.Value
            if self.spy_sma50.IsReady:
                self.previous_spy_sma50 = self.spy_sma50.Current.Value
            self.previous_spy_close = spy_bar.Close
